operation.add:
// ProBG Team
$this->load->language('extension/module/probg_team');
$probg_team = array();
if ($this->user->hasPermission('access', 'extension/probg_team/member')) {
    $probg_team[] = array('name' => $this->language->get('text_team_members'), 'href' => $this->url->link('extension/probg_team/member', 'user_token=' . $this->session->data['user_token'], true), 'children' => array());
}
if ($this->user->hasPermission('access', 'extension/probg_team/category')) {
    $probg_team[] = array('name' => $this->language->get('text_team_categories'), 'href' => $this->url->link('extension/probg_team/category', 'user_token=' . $this->session->data['user_token'], true), 'children' => array());
}
if ($this->user->hasPermission('access', 'extension/module/probg_team') || $this->user->hasPermission('access', 'extension/probg_team/setting')) {
    $probg_team[] = array('name' => $this->language->get('text_team_settings'), 'href' => $this->url->link('extension/module/probg_team', 'user_token=' . $this->session->data['user_token'], true), 'children' => array());
}
if ($probg_team) $data['menus'][] = array('id' => 'menu-probg-team', 'icon' => 'fa-users', 'name' => $this->language->get('text_probg_team_menu'), 'href' => '', 'children' => $probg_team);

if ($url[0] == 'probg_team_section') {
    $this->request->get['probg_team_section'] = $url[1];
    continue;
}

if ($url[0] == 'probg_team_category_id') {
    $this->request->get['probg_team_category_id'] = $url[1];
    continue;
}

if ($url[0] == 'probg_team_member_id') {
    $this->request->get['probg_team_member_id'] = $url[1];
    continue;
}

if (isset($data['route']) && in_array($data['route'], array('extension/probg_team/team', 'extension/probg_team/category', 'extension/probg_team/member'))) {
    $probg_team_queries = array('probg_team_section=1');

    if ($data['route'] == 'extension/probg_team/category') {
        if (empty($data['probg_team_category_id'])) {
            return $link;
        }

        $probg_team_queries[] = 'probg_team_category_id=' . (int)$data['probg_team_category_id'];
    }

    if ($data['route'] == 'extension/probg_team/member') {
        if (empty($data['probg_team_member_id'])) {
            return $link;
        }

        if (empty($data['probg_team_category_id'])) {
            $probg_team_member_query = $this->db->query("SELECT team_category_id FROM `" . DB_PREFIX . "team_member` WHERE team_member_id = '" . (int)$data['probg_team_member_id'] . "' LIMIT 1");

            if (!$probg_team_member_query->num_rows) {
                return $link;
            }

            $data['probg_team_category_id'] = (int)$probg_team_member_query->row['team_category_id'];
        }

        $probg_team_queries[] = 'probg_team_category_id=' . (int)$data['probg_team_category_id'];
        $probg_team_queries[] = 'probg_team_member_id=' . (int)$data['probg_team_member_id'];
    }

    $probg_team_url = '';

    foreach ($probg_team_queries as $probg_team_query_key) {
        $probg_team_seo_query = $this->db->query("SELECT keyword FROM `" . DB_PREFIX . "seo_url` WHERE `query` = '" . $this->db->escape($probg_team_query_key) . "' AND store_id = '" . (int)$this->config->get('config_store_id') . "' AND language_id = '" . (int)$this->config->get('config_language_id') . "' LIMIT 1");

        if (!$probg_team_seo_query->num_rows || !$probg_team_seo_query->row['keyword']) {
            return $link;
        }

        $probg_team_url .= '/' . $probg_team_seo_query->row['keyword'];
    }

    unset($data['route']);
    unset($data['probg_team_section']);
    unset($data['probg_team_category_id']);
    unset($data['probg_team_member_id']);

    $probg_team_query_string = $data ? '?' . http_build_query($data, '', '&amp;', PHP_QUERY_RFC3986) : '';

    return $url_info['scheme'] . '://' . $url_info['host'] . (isset($url_info['port']) ? ':' . $url_info['port'] : '') . str_replace('/index.php', '', $url_info['path']) . $probg_team_url . $probg_team_query_string;
}

{% if probg_team_og_title %}
<meta property="og:title" content="{{ probg_team_og_title }}" />
<meta property="og:type" content="{{ probg_team_og_type|default('website') }}" />
<meta property="og:url" content="{{ probg_team_og_url }}" />
<meta property="og:site_name" content="{{ probg_team_og_site_name }}" />
{% if probg_team_og_description %}<meta property="og:description" content="{{ probg_team_og_description }}" />{% endif %}
{% if probg_team_og_image %}<meta property="og:image" content="{{ probg_team_og_image }}" />{% endif %}
<meta name="twitter:card" content="{% if probg_team_og_image %}summary_large_image{% else %}summary{% endif %}" />
<meta name="twitter:title" content="{{ probg_team_og_title }}" />
{% if probg_team_og_description %}<meta name="twitter:description" content="{{ probg_team_og_description }}" />{% endif %}
{% if probg_team_og_image %}<meta name="twitter:image" content="{{ probg_team_og_image }}" />{% endif %}
{% endif %}

$data['probg_team_search_results'] = array();
$data['probg_team_search_heading'] = '';

if ($this->config->get('module_probg_team_status') && $this->config->get('module_probg_team_search_status') && isset($this->request->get['search']) && trim($this->request->get['search']) !== '') {
    $this->load->language('extension/probg_team/team');
    $this->load->model('extension/probg_team/team');
    $this->load->model('tool/image');
    $this->document->addStyle('catalog/view/javascript/probg_team/probg_team.css');

    $probg_team_search_limit = max(1, (int)$this->config->get('module_probg_team_search_limit'));
    $probg_team_search_results = $this->model_extension_probg_team_team->searchMembers($this->request->get['search'], $probg_team_search_limit);
    $probg_team_image_width = max(1, (int)$this->config->get('module_probg_team_list_width'));
    $probg_team_image_height = max(1, (int)$this->config->get('module_probg_team_list_height'));

    foreach ($probg_team_search_results as $probg_team_result) {
        if ($probg_team_result['image'] && is_file(DIR_IMAGE . $probg_team_result['image'])) {
            $probg_team_image = $this->model_tool_image->resize($probg_team_result['image'], $probg_team_image_width, $probg_team_image_height);
        } else {
            $probg_team_image = $this->model_tool_image->resize('placeholder.png', $probg_team_image_width, $probg_team_image_height);
        }

        $probg_team_description = trim(strip_tags(html_entity_decode($probg_team_result['short_description'], ENT_QUOTES, 'UTF-8')));

        $data['probg_team_search_results'][] = array(
            'name' => $probg_team_result['name'],
            'category' => $probg_team_result['category_name'],
            'city' => $probg_team_result['city'],
            'thumb' => $probg_team_image,
            'description' => utf8_substr($probg_team_description, 0, 180) . (utf8_strlen($probg_team_description) > 180 ? '...' : ''),
            'href' => $this->url->link('extension/probg_team/member', 'probg_team_category_id=' . (int)$probg_team_result['team_category_id'] . '&probg_team_member_id=' . (int)$probg_team_result['team_member_id'])
        );
    }

    $data['probg_team_search_heading'] = $this->language->get('text_team_search_results');
    $data['probg_team_text_view_profile'] = $this->language->get('text_read_more');
    $data['probg_team_text_category'] = $this->language->get('text_category');
    $data['probg_team_text_city'] = $this->language->get('text_city');
}

{% if probg_team_search_results %}
<div class="probg-team-search-results">
  <h2>{{ probg_team_search_heading }}</h2>
  <div class="row probg-team-grid">
    {% for member in probg_team_search_results %}
    <div class="col-xs-12 col-sm-6 col-md-4">
      <div class="thumbnail probg-team-card">
        <a href="{{ member.href }}" class="image"><img src="{{ member.thumb }}" alt="{{ member.name }}" class="img-responsive" loading="lazy" /></a>
        <div class="caption">
          <h3><a href="{{ member.href }}">{{ member.name }}</a></h3>
          {% if member.category %}<p><strong>{{ probg_team_text_category }}:</strong> {{ member.category }}</p>{% endif %}
          {% if member.city %}<p><strong>{{ probg_team_text_city }}:</strong> {{ member.city }}</p>{% endif %}
          {% if member.description %}<p>{{ member.description }}</p>{% endif %}
          <p><a href="{{ member.href }}" class="btn btn-primary">{{ probg_team_text_view_profile }}</a></p>
        </div>
      </div>
    </div>
    {% endfor %}
  </div>
</div>
{% endif %}

if ($this->config->get('module_probg_team_status') && $this->config->get('module_probg_team_sitemap_status')) {
    $this->load->model('extension/probg_team/team');
    $probg_team_section = $this->model_extension_probg_team_team->getSectionDescription();

    if ($probg_team_section) {
        $output .= '<url>';
        $output .= '<loc>' . $this->url->link('extension/probg_team/team') . '</loc>';
        $output .= '<changefreq>weekly</changefreq>';
        $output .= '<priority>0.8</priority>';
        $output .= '</url>';

        foreach ($this->model_extension_probg_team_team->getSitemapCategories() as $probg_team_category) {
            $output .= '<url>';
            $output .= '<loc>' . $this->url->link('extension/probg_team/category', 'probg_team_category_id=' . (int)$probg_team_category['team_category_id']) . '</loc>';
            $output .= '<changefreq>weekly</changefreq>';
            $output .= '<lastmod>' . date('Y-m-d\TH:i:sP', strtotime($probg_team_category['date_modified'])) . '</lastmod>';
            $output .= '<priority>0.7</priority>';
            $output .= '</url>';
        }

        foreach ($this->model_extension_probg_team_team->getSitemapMembers() as $probg_team_member) {
            $output .= '<url>';
            $output .= '<loc>' . $this->url->link('extension/probg_team/member', 'probg_team_category_id=' . (int)$probg_team_member['team_category_id'] . '&probg_team_member_id=' . (int)$probg_team_member['team_member_id']) . '</loc>';
            $output .= '<changefreq>weekly</changefreq>';
            $output .= '<lastmod>' . date('Y-m-d\TH:i:sP', strtotime($probg_team_member['date_modified'])) . '</lastmod>';
            $output .= '<priority>0.6</priority>';
            $output .= '</url>';
        }
    }
}
